use titan_audio_link::Client;fn main(){let mut c=Client::new().unwrap();assert!(c.call("check",serde_json::json!({})).is_err());if std::env::args().len()>1{let tests:serde_json::Value=serde_json::from_str(include_str!("../docs/contract.json")).unwrap();for t in tests.as_array().unwrap(){let r=c.call(t["operation"].as_str().unwrap(),t["arguments"].clone()).unwrap();let value=&r[t["expected_key"].as_str().unwrap()];if let Some(expected)=t.get("expected_value"){assert_eq!(value,expected);}if let Some(min)=t.get("minimum_length"){assert!(value.as_array().unwrap().len()>=min.as_u64().unwrap() as usize);}}}c.close().unwrap();}
